<script lang="ts">import {createMenuController} from "@weiui/core";import {normalizeSvelteProps} from "./internal.js";type Item={value:string;label?:string;disabled?:boolean};let {items=[],trigger="Menu",id="wui-menu",onselect}=$props<{items?:Item[];trigger?:string;id?:string;onselect?:(value:string)=>void}>();const controller=createMenuController({id});controller.setItems(items);let state=$state(controller.getState());$effect(()=>{const off=controller.subscribe(next=>state=next);return off});$effect(()=>controller.setItems(items));function p(kind:"root"|"trigger"|"content"|"item",index=0){state;return normalizeSvelteProps(kind==="root"?controller.getRootProps():kind==="trigger"?controller.getTriggerProps():kind==="content"?controller.getContentProps():controller.getItemProps(index))}</script><div {...p("root")} class="wui-menu"><button {...p("trigger")} class="wui-menu__trigger">{trigger}</button><div {...p("content")} class="wui-menu__content">{#each items as item,index (item.value)}<div {...p("item",index)} class="wui-menu__item" onclick={(event)=>{p("item",index).onclick?.(event);if(!item.disabled)onselect?.(item.value)}}>{item.label??item.value}</div>{/each}</div></div>
